import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';

const NotificationContext = createContext();

export const useNotifications = () => {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotifications must be used within a NotificationProvider');
  }
  return context;
};

export const NotificationProvider = ({ children }) => {
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);

  // Mock data for demonstration
  useEffect(() => {
    const mockNotifications = [
      {
        id: '1',
        type: 'success',
        title: 'Payment Successful',
        message: 'Your payment of $250.00 to John Doe has been processed successfully.',
        timestamp: new Date(Date.now() - 5 * 60 * 1000), // 5 minutes ago
        read: false,
        category: 'payment'
      },
      {
        id: '2',
        type: 'info',
        title: 'Account Statement Ready',
        message: 'Your monthly account statement for December 2023 is now available.',
        timestamp: new Date(Date.now() - 2 * 60 * 60 * 1000), // 2 hours ago
        read: false,
        category: 'account'
      },
      {
        id: '3',
        type: 'warning',
        title: 'Low Balance Alert',
        message: 'Your checking account balance is below $100. Consider transferring funds.',
        timestamp: new Date(Date.now() - 24 * 60 * 60 * 1000), // 1 day ago
        read: true,
        category: 'alert'
      },
      {
        id: '4',
        type: 'error',
        title: 'Failed Transaction',
        message: 'Payment to ABC Store was declined. Please check your account balance.',
        timestamp: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000), // 3 days ago
        read: true,
        category: 'payment'
      }
    ];
    
    setNotifications(mockNotifications);
    setUnreadCount(mockNotifications.filter(n => !n.read).length);
  }, []);

  const addNotification = useCallback((notification) => {
    const id = Date.now().toString() + Math.random().toString(36).substr(2, 9);
    const newNotification = {
      id,
      type: 'info',
      timestamp: new Date(),
      read: false,
      category: 'general',
      ...notification
    };
    
    setNotifications(prev => [newNotification, ...prev]);
    setUnreadCount(prev => prev + 1);
    
    return id;
  }, []);

  const markAsRead = useCallback((id) => {
    setNotifications(prev => prev.map(notification => {
      if (notification.id === id && !notification.read) {
        setUnreadCount(count => Math.max(0, count - 1));
        return { ...notification, read: true };
      }
      return notification;
    }));
  }, []);

  const markAllAsRead = useCallback(() => {
    setNotifications(prev => prev.map(notification => ({ ...notification, read: true })));
    setUnreadCount(0);
  }, []);

  const removeNotification = useCallback((id) => {
    setNotifications(prev => {
      const notification = prev.find(n => n.id === id);
      if (notification && !notification.read) {
        setUnreadCount(count => Math.max(0, count - 1));
      }
      return prev.filter(n => n.id !== id);
    });
  }, []);

  const clearAllNotifications = useCallback(() => {
    setNotifications([]);
    setUnreadCount(0);
  }, []);

  const getNotificationsByType = useCallback((type) => {
    return notifications.filter(notification => notification.type === type);
  }, [notifications]);

  const getUnreadNotifications = useCallback(() => {
    return notifications.filter(notification => !notification.read);
  }, [notifications]);

  const getNotificationsByCategory = useCallback((category) => {
    return notifications.filter(notification => notification.category === category);
  }, [notifications]);

  // Convenience methods for different notification types
  const addPaymentNotification = useCallback((title, message, success = true) => {
    return addNotification({
      type: success ? 'success' : 'error',
      title,
      message,
      category: 'payment'
    });
  }, [addNotification]);

  const addAccountNotification = useCallback((title, message, type = 'info') => {
    return addNotification({
      type,
      title,
      message,
      category: 'account'
    });
  }, [addNotification]);

  const addSecurityNotification = useCallback((title, message, type = 'warning') => {
    return addNotification({
      type,
      title,
      message,
      category: 'security'
    });
  }, [addNotification]);

  const addAlertNotification = useCallback((title, message, type = 'warning') => {
    return addNotification({
      type,
      title,
      message,
      category: 'alert'
    });
  }, [addNotification]);

  const value = {
    notifications,
    unreadCount,
    addNotification,
    markAsRead,
    markAllAsRead,
    removeNotification,
    clearAllNotifications,
    getNotificationsByType,
    getUnreadNotifications,
    getNotificationsByCategory,
    addPaymentNotification,
    addAccountNotification,
    addSecurityNotification,
    addAlertNotification
  };

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  );
};

export default NotificationContext;